<?php
require 'config.php';require_login();verify_csrf();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$load=(int)$_POST['load_id'];$q=db()->prepare("SELECT * FROM loads WHERE id=?");$q->execute([$load]);$l=$q->fetch();if(!$l)throw new RuntimeException('Choose a valid load.');$invoice='INV-'.date('Ymd').'-'.str_pad((string)random_int(1,9999),4,'0',STR_PAD_LEFT);$due=$_POST['due_date']?:date('Y-m-d',strtotime('+30 days'));$s=db()->prepare("INSERT INTO invoices(load_id,invoice_no,invoice_date,due_date,amount,status) VALUES(?,?,?,?,?,'Sent')");$s->execute([$load,$invoice,date('Y-m-d'),$due,$l['rate']]);db()->prepare("UPDATE loads SET status='Invoiced' WHERE id=? AND status='Delivered'")->execute([$load]);flash('success','Invoice '.$invoice.' created.');redirect('invoices.php');}catch(Throwable $e){$error=$e->getMessage();}}
if(isset($_GET['paid'])&&current_user()['role']==='admin'){db()->prepare("UPDATE invoices SET status='Paid',paid_date=CURDATE(),payment_reference=? WHERE id=?")->execute([$_GET['ref']??null,(int)$_GET['paid']]);db()->prepare("UPDATE loads l JOIN invoices i ON i.load_id=l.id SET l.status='Paid' WHERE i.id=?")->execute([(int)$_GET['paid']]);flash('success','Invoice marked as paid.');redirect('invoices.php');}
$loads=db()->query("SELECT id,load_no,rate FROM loads WHERE status IN ('Delivered','Invoiced','Paid') ORDER BY id DESC")->fetchAll();$rows=db()->query("SELECT i.*,l.load_no,b.company_name FROM invoices i JOIN loads l ON l.id=i.load_id LEFT JOIN brokers b ON b.id=l.broker_id ORDER BY i.id DESC")->fetchAll();$pageTitle='Invoices & Payments';$active='invoices';require 'partials_header.php';?>
<div class="page-head"><div><h1>Broker invoices & payments</h1><p>Create load invoices, monitor due dates and record broker payments.</p></div></div><div class="form-card" style="margin-bottom:20px"><h3>Generate invoice from delivered load</h3><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field"><label>Delivered load *</label><select name="load_id" required><?php foreach($loads as $l):?><option value="<?=$l['id']?>"><?=e($l['load_no'])?> · <?=money($l['rate'])?></option><?php endforeach;?></select></div><div class="field"><label>Due date</label><input type="date" name="due_date"></div></div><div class="form-actions"><button class="btn primary">Create invoice</button></div></form></div>
<div class="table-wrap"><table class="table"><thead><tr><th>Invoice</th><th>Load</th><th>Broker</th><th>Invoice date</th><th>Due date</th><th>Amount</th><th>Status</th><th>Follow-up</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['invoice_no'])?></td><td><?=e($r['load_no'])?></td><td><?=e($r['company_name']??'—')?></td><td><?=e($r['invoice_date'])?></td><td><?=e($r['due_date'])?></td><td><?=money($r['amount'])?></td><td><span class="badge <?=$r['status']==='Paid'?'green':($r['status']==='Overdue'?'red':'amber')?>"><?=e($r['status'])?></span></td><td><?php if($r['status']!=='Paid'):?><a href="?paid=<?=$r['id']?>" onclick="return confirm('Mark invoice paid?')">Record payment</a><?php else:?>Paid <?=e($r['paid_date'])?><?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8" class="empty">No invoices created.</td></tr><?php endif;?></tbody></table></div><?php require 'partials_footer.php';?>